class Bruch {
  private int zaehler, nenner;

  public Bruch(int zaehler, int nenner) {
    int g = ggt(Math.abs(zaehler), Math.abs(nenner));
    this.zaehler = zaehler / g;
    this.nenner  = nenner / g;
  }
