class Punkt {
  private int x, y;

  public Punkt(int x, int y) {
    this.x = x;
    this.y = y;
  }
  public void verschiebe(int dx, int dy) {
    this.x = this.x + dx;
    this.y = this.y + dy;
  }
  public double abstandZu(Punkt anderer) {
    int dx = this.x - anderer.x;
    int dy = this.y - anderer.y;
    return Math.sqrt(dx * dx + dy * dy);
  }
  public String toString() {
    return "(" + x + "," + y + ")";
  }
}
class PunktApp {
  public static void main(String[] s) {
    Punkt p1 = new Punkt(1, 2);
    Punkt p2 = new Punkt(4, 6);
    System.out.println( p1 );
    System.out.println( p2 );
    System.out.println( p1.abstandZu(p2) );
    p1.verschiebe(3, 4);
    System.out.println( p1 );
    System.out.println( p1.abstandZu(p2) );
  }
}

