class Konto {
  public static final double ZINSSATZ = 0.02;
  private static int anzahl = 0;

  private String inhaber;
  private double stand;

  public Konto(String inhaber, double stand) {
    this.inhaber = inhaber;
    this.stand = stand;
    anzahl++;
  }
  public Konto(String inhaber) {
    this(inhaber, 0.0);
  }
  public void einzahlen(double betrag) {
    if (betrag > 0)
      stand = stand + betrag;
  }
  public boolean abheben(double betrag) {
    if (betrag > 0 && betrag <= stand) {
      stand = stand - betrag;
      return true;
    }
    return false;
  }
  public double zinsen() {
    return stand * ZINSSATZ;
  }
  public double getStand() { return stand; }

  public static int getAnzahl() { return anzahl; }

  public String toString() {
    return inhaber + ": " + stand;
  }
}
class KontoApp {
  public static void main(String[] s) {
    Konto a = new Konto("Meier", 500.0);
    Konto b = new Konto("Schmidt");
    b.einzahlen(200.0);
    System.out.println( a );
    System.out.println( b );
    System.out.println( a.abheben(600.0) );
    System.out.println( a.abheben(100.0) );
    System.out.println( a.getStand() );
    System.out.println( a.zinsen() );
    System.out.println( Konto.getAnzahl() );
  }
}

