class Rechner {
  private int aufrufe = 0;

  public long potenz(long basis, int exponent) {
    aufrufe++;
    if (exponent == 0)
      return 1L;
    return basis * potenz(basis, exponent - 1);
  }
  public long potenz(long basis) {
    return potenz(basis, 2);
  }
  public int getAufrufe() { return aufrufe; }
}
class RechnerApp {
  public static void main(String[] s) {
    Rechner r = new Rechner();
    System.out.println( r.potenz(2, 10) );
    System.out.println( r.potenz(5) );
    System.out.println( r.getAufrufe() );
  }
}

